-- Schema and migration markers of a database created by the benchmark branch
-- at commit b85bc0ea0 ("feat: embed benchmark engine and evaluation workflow"),
-- the last commit before that branch renumbered its migrations to 41 and 42
-- (e4531e3e6). Produced by store.Open on an empty file at that commit and
-- dumped from sqlite_master; seeded rows are omitted. That branch recorded 37,
-- 38 and 40 under benchmark names and never recorded 39.
CREATE TABLE `ai_configs` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text,`preset` text,`base_url` text,`api_key` text,`model` text,`is_default` numeric,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `api_keys` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text,`prefix` text,`hash` text,`user_id` integer,`created_at` datetime,`last_used` datetime);
CREATE TABLE `benchmark_baselines` (`id` integer PRIMARY KEY AUTOINCREMENT,`source` text,`label` text,`model` text,`hardware` text,`engine` text,`num_gp_us` integer,`isl` integer,`osl` integer,`concurrency` integer,`metrics` text,`snapshot_date` text,`notes` text,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `benchmark_points` (`id` integer PRIMARY KEY AUTOINCREMENT,`run_id` integer,`seq` integer,`concurrency` integer,`target_isl` integer,`target_osl` integer,`repeat` integer,`state` text,`actual_isl` real,`actual_osl` real,`input_tokens` integer,`output_tokens` integer,`success` integer,`errors` integer,`output_tput` real,`total_tput` real,`request_tput` real,`avg_ttft` real,`p50_ttft` real,`p99_ttft` real,`avg_tpot` real,`p50_tpot` real,`p99_tpot` real,`avg_latency` real,`p50_latency` real,`p99_latency` real,`long_tail` text,`detail_path` text,`started_at` datetime,`ended_at` datetime,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `benchmark_runs` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text,`target_kind` text,`deployment_id` integer,`instance_uuid` text,`base_url` text,`api_key` text,`model` text,`load_origin` text,`num_gp_us` integer,`dataset` text,`mode` text,`search` text,`tokenizer_ref` text,`keep_detail` numeric,`detail_cap_mb` integer,`state` text,`progress` text,`error` text,`created_by` integer,`started_at` datetime,`ended_at` datetime,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `deployments` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text,`model_id` integer,`node_id` integer,`node_ids` text,`served_name` text,`engine` text,`image` text,`quick_params` text,`extra_args` text,`env` text,`run_spec_overrides` text,`replicas` integer,`v_ram_limit_bytes` integer,`sm_limit_pct` integer,`sleepable` numeric,`desired_sleep` integer,`placement` text,`dist_group` text,`dist_role` text,`n_nodes` integer,`node_rank` integer,`master_addr` text,`master_port` integer,`restart_count` integer,`state` text,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `gpus` (`id` integer PRIMARY KEY AUTOINCREMENT,`node_id` integer,`index` integer,`uuid` text,`name` text,`compute_capability` text,`arch_family` text,`vendor` text,`arch_id` text,`memory_total` integer,`power_limit_watts` real,`pc_ie_bdf` text,`numa_node` integer,`partition_mode` text,`mig_enabled` numeric,`healthy` numeric,`health_status` text,`health_code` text,`health_message` text,`created_at` datetime,`updated_at` datetime,CONSTRAINT `fk_nodes_gp_us` FOREIGN KEY (`node_id`) REFERENCES `nodes`(`id`) ON DELETE CASCADE);
CREATE TABLE `image_nodes` (`id` integer PRIMARY KEY AUTOINCREMENT,`image_version_id` integer,`node_id` integer,`state` text,`size_bytes` integer,`transferred_bytes` integer,`rate_bps` integer,`transfer_id` text,`source_node_id` integer,`source` text,`message` text,`image_digest_id` text,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `image_series` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text,`engine` text,`purpose` text,`framework` text,`vendors` text,`source` text,`deprecated_since` text,`notes` text,`enabled` numeric,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `image_versions` (`id` integer PRIMARY KEY AUTOINCREMENT,`series_id` integer,`name` text,`engine` text,`engine_version` text,`framework` text,`framework_version` text,`variant` text,`arch` text,`image_ref` text,`source` text,`vendors` text,`env` text,`docker_args` text,`run_command` text,`deprecated` numeric,`enabled` numeric,`size_bytes` integer,`notes` text,`offline_blob_path` text,`offline_blob_sha256` text,`offline_blob_bytes` integer,`expected_image_id` text,`verify_state` text,`verify_message` text,`model_mount_path` text,`extra_mounts` text,`entrypoint_display` text,`cmd_display` text,`inspect_synced` numeric,`adapted_models` text,`deprecated_since` text,`registry_sources` text,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `instance_events` (`id` integer PRIMARY KEY AUTOINCREMENT,`instance_id` integer,`kind` text,`message` text,`data` text,`created_at` datetime);
CREATE TABLE `instances` (`id` integer PRIMARY KEY AUTOINCREMENT,`uuid` text,`deployment_id` integer,`node_id` integer,`state` text,`gp_uindexes` text,`ports` text,`api_port` integer,`container_id` text,`image` text,`spec` text,`run_spec_snapshot` text,`run_spec_overrides` text,`injected_args` text,`measured` text,`schedule_expl` text,`direct_addr` text,`message` text,`phase` text,`progress` real,`bytes_done` integer,`bytes_total` integer,`rate_bps` integer,`sleep_level` integer,`dist_group` text,`dist_role` text,`n_nodes` integer,`node_rank` integer,`headless` numeric,`dist_attempt` integer,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `legacy_jobs` (`id` integer PRIMARY KEY AUTOINCREMENT,`kind` text,`name` text,`state` text,`params` text,`spec` text,`result` text,`node_id` integer,`message` text,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `model_files` (`id` integer PRIMARY KEY AUTOINCREMENT,`model_id` integer,`node_id` integer,`path` text,`state` text,`size_bytes` integer,`downloaded` integer,`transferred_bytes` integer,`rate_bps` integer,`rate_limit` integer,`message` text,`acquisition` text,`transfer_id` text,`transfer_source_node_id` integer,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `models` (`id` integer PRIMARY KEY AUTOINCREMENT,`source` text,`source_id` text,`revision` text,`name` text,`arch` text,`quant_label` text,`weight_bytes` integer,`dtype` text,`vllm_support` text,`engine_support` text,`meta` text,`image_id` integer,`readme` text,`logo_path` text,`origin_created_at` datetime,`origin_updated_at` datetime,`context_length` integer,`precision` text,`capability_override` text,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `nodes` (`id` integer PRIMARY KEY AUTOINCREMENT,`uuid` text,`name` text,`token` text DEFAULT null,`token_hash` text,`agent_version` text,`state` text,`hostname` text,`labels` text,`os` text,`kernel` text,`arch` text,`cpu_model` text,`cpu_cores` integer,`mem_total_kb` integer,`disk_total_kb` integer,`gpu_count` integer,`gpu_vendor` text,`gpu_driver` text,`nvidia_driver` text,`framework` text,`framework_version` text,`models_root` text,`path_usage` text,`direct_address` text,`connect_mode` text,`server_dial_address` text,`last_remote_addr` text,`runtime_driver` text,`runtimes` text,`partition_mode` text,`last_reject_reason` text,`last_reject_at` datetime,`last_seen_at` datetime,`created_at` datetime,`updated_at` datetime,`topo_raw` text,`topo_json` text);
CREATE TABLE `profiles` (`id` integer PRIMARY KEY AUTOINCREMENT,`fingerprint` text,`model_id` integer,`node_id` integer,`engine` text,`vendor` text,`arch_id` text,`args_hash` text,`measured` text,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `provider_bootstrap_tokens` (`id` integer PRIMARY KEY AUTOINCREMENT,`token_hash` text,`provider_id` integer,`external_id` text,`node_id` integer,`expires_at` datetime,`used_at` datetime,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `provider_instances` (`id` integer PRIMARY KEY AUTOINCREMENT,`provider_id` integer,`external_id` text,`name` text,`gpu_model` text,`gpu_count` integer,`power` text,`price_per_hr` real,`region` text,`public_ip` text,`ssh_port` integer,`ssh_user` text,`kind` text,`node_id` integer,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `providers` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text,`kind` text,`creds_cipher` text,`state` text,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `schema_migrations` (`version` integer PRIMARY KEY AUTOINCREMENT,`name` text,`applied_at` datetime);
CREATE TABLE `settings` (`key` text,`value` text,`updated_at` datetime,PRIMARY KEY (`key`));
CREATE TABLE `storages` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text,`type` text,`enabled` numeric,`builtin` numeric,`config` text,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `terminal_sessions` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer,`username` text,`node_uuid` text,`target` text,`ref` text,`client_ip` text,`started_at` datetime,`ended_at` datetime,`bytes_in` integer,`bytes_out` integer,`close_reason` text);
CREATE TABLE `users` (`id` integer PRIMARY KEY AUTOINCREMENT,`username` text,`password_hash` text,`role` text,`created_at` datetime,`updated_at` datetime);
